# DP for linear chain (path without final edge)
# Let's implement DP via maintaining partition of {0,n,i}
from itertools import product

def all_partitions_of_3():
    partitions=[]
    def rec(idx, cur):
        if idx==3:
            partitions.append([set(b) for b in cur])
            return
        for i in range(len(cur)):
            cur[i].add(idx)
            rec(idx+1, cur)
            cur[i].remove(idx)
        cur.append({idx})
        rec(idx+1, cur)
        cur.pop()
    rec(0, [])
    return partitions

parts=all_partitions_of_3()

def connected(part,a,b):
    for block in part:
        if a in block:
            return b in block
    return False

def dp_forests_linear(n,s):
    def part_to_idx(part):
        c=tuple(sorted([frozenset(b) for b in part], key=lambda x: (min(x), len(x))))
        for idx,p in enumerate(parts):
            cc=tuple(sorted([frozenset(b) for b in p], key=lambda x: (min(x), len(x))))
            if c==cc:
                return idx
        raise ValueError("not found")

    def merge_partition(part, a,b):
        new_blocks=[]
        block_a=None
        block_b=None
        for block in part:
            if a in block:
                block_a=block
            if b in block:
                block_b=block
        if block_a is block_b:
            return [set(b) for b in part]
        merged= set(block_a)|set(block_b)
        for block in part:
            if block is block_a or block is block_b:
                continue
            new_blocks.append(set(block))
        new_blocks.append(merged)
        return new_blocks

    def project_and_rename(ext, old_to_drop):
        new_blocks=[]
        for block in ext:
            nb = set(block)
            if old_to_drop in nb:
                nb.remove(old_to_drop)
                if len(nb)==0:
                    continue
            new_blocks.append(nb)
        renamed=[]
        for block in new_blocks:
            nb=set()
            for e in block:
                if e==3:
                    nb.add(2)
                else:
                    nb.add(e)
            renamed.append(nb)
        return renamed

    def step(part, s_char, is_last):
        results=[]
        spoke_partitions=[]
        if s_char=='1':
            spoke_partitions.append([set(b) for b in part])
            if not connected(part,1,2):
                merged=merge_partition(part,1,2)
                spoke_partitions.append(merged)
        else:
            spoke_partitions.append([set(b) for b in part])
        if is_last:
            for p in spoke_partitions:
                results.append(p)
        else:
            for p in spoke_partitions:
                ext=[set(b) for b in p]
                ext.append({3})
                new_p_exclude = project_and_rename(ext, old_to_drop=2)
                results.append(new_p_exclude)
                ext_inc = merge_partition(ext,2,3)
                new_p_include = project_and_rename(ext_inc, old_to_drop=2)
                results.append(new_p_include)
        return results

    init_part=None
    for p in parts:
        if connected(p,0,2) and not connected(p,0,1) and not connected(p,1,2):
            init_part=p
            break
    dp={part_to_idx(init_part):1}
    for i in range(n):
        s_char=s[i]
        is_last = (i==n-1)
        new_dp={}
        for idx,cnt in dp.items():
            part=parts[idx]
            results=step(part,s_char,is_last)
            for r in results:
                r_idx=part_to_idx(r)
                new_dp[r_idx]=new_dp.get(r_idx,0)+cnt
        dp=new_dp
    total=sum(dp.values())
    return total, dp

def brute_linear(n,s):
    edges=[]
    for i in range(n-1):
        edges.append((i,i+1))
    for i,ch in enumerate(s):
        if ch=='1':
            edges.append((i,n))
    m=len(edges)
    def is_forest(mask):
        parent=list(range(n+1))
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]]
                x=parent[x]
            return x
        def union(a,b):
            ra=find(a); rb=find(b)
            if ra==rb:
                return False
            parent[rb]=ra
            return True
        for idx,(u,v) in enumerate(edges):
            if (mask>>idx)&1:
                if not union(u,v):
                    return False
        return True
    cnt=0
    for mask in range(1<<m):
        if is_forest(mask):
            cnt+=1
    return cnt

def test_dp_linear_vs_brute():
    for n,s in [(3,'010'),(4,'1000'),(4,'0101'),(5,'00000'),(3,'000'),(4,'0010')]:
        bl=brute_linear(n,s)
        dp_total,_=dp_forests_linear(n,s)
        print(f"n={n} s={s} brute_linear={bl} dp={dp_total} match={bl==dp_total}")
        assert bl==dp_total

def test_final_cycle():
    # try to close cycle edge (n-1)-0 and get total forests of full graph
    # after dp linear, we have partitions of {0,n,n-1} (since current is n-1)
    # edge (n-1)-0 connects 0 and 2 (where 2 is current representing n-1)
    # number of final forests = sum over dp states of number of valid selections for final edge (0 if connected else 1+1)
    for n,s in [(3,'010'),(4,'1000'),(4,'0101'),(5,'00000'),(3,'000'),(4,'0010'),(8,'01000101'),(10,'0000000000'),(5,'10000')]:
        # compute brute full
        brute_full=brute_forests(n,s)
        total_linear, dp = dp_forests_linear(n,s)
        # need mapping from partition idx to whether 0 and 2 connected
        # we have parts global
        # For each dp state, count contributions:
        sum_final=0
        for idx,cnt in dp.items():
            part=parts[idx]
            # check if 0 and 2 connected in this partition
            # Note: after linear dp, partition includes {0, apex, last}
            if connected(part,0,2):
                # final edge would create cycle, cannot include it
                sum_final+=cnt # only exclude option
            else:
                sum_final+=cnt*2 # both exclude/include
        print(f"n={n} s={s} brute_full={brute_full} dp_final={sum_final} match={brute_full==sum_final}")
        assert brute_full==sum_final
