def test_final_cycle():
    # try to close cycle edge (n-1)-0 and get total forests of full graph
    # after dp linear, we have partitions of {0,n,n-1} (since current is n-1)
    # edge (n-1)-0 connects 0 and 2 (where 2 is current representing n-1)
    # number of final forests = sum over dp states of number of valid selections for final edge (0 if connected else 1+1)
    for n,s in [(3,'010'),(4,'1000'),(4,'0101'),(5,'00000'),(3,'000'),(4,'0010'),(8,'01000101'),(10,'0000000000'),(5,'10000')]:
