        # need mapping from partition idx to whether 0 and 2 connected
        # we have parts global
        # For each dp state, count contributions:
        sum_final=0
        for idx,cnt in dp.items():
            part=parts[idx]
            # check if 0 and 2 connected in this partition
            # Note: after linear dp, partition includes {0, apex, last}
            if connected(part,0,2):
                # final edge would create cycle, cannot include it
                sum_final+=cnt # only exclude option
            else:
                sum_final+=cnt*2 # both exclude/include
        print(f"n={n} s={s} brute_full={brute_full} dp_final={sum_final} match={brute_full==sum_final}")
